(6597071, 983252, 94265, '<td valign="top">Very nice, the stormy looking sky in the background adds to the mood; a very good and sharp image. I can see this ranking quite high.</td>', 'Very nice, the stormy looking sky in the background adds to the mood; a very good and sharp image. I can see this ranking quite high.', '2011-11-17 10:05:07.000000', NULL, 1),
(6597075, 983530, 94265, '<td valign="top">Interesting little wall; different colours, shapes, words, all keep this from being dull without being too busy. I like it, nice sharpness too.</td>', 'Interesting little wall; different colours, shapes, words, all keep this from being dull without being too busy. I like it, nice sharpness too.', '2011-11-17 10:10:24.000000', NULL, 1),
(6597079, 984149, 94265, '<td valign="top">Lovely place, some great patterns on the woodwork, nice light and shadows too. I like this shot a lot but I do wish it was rotated just a little to the left as it''s sitting slightly skewed. Maybe taking the shot a wee bit more to the right facing the door dead on would have rectified that. Very nice overall though.</td>', 'Lovely place, some great patterns on the woodwork, nice light and shadows too. I like this shot a lot but I do wish it was rotated just a little to the left as it''s sitting slightly skewed. Maybe taking the shot a wee bit more to the right facing the door dead on would have rectified that. Very nice overall though.', '2011-11-17 10:15:26.000000', NULL, 1),
(6597083, 984138, 94265, '<td valign="top">I love the focus on this, the little eye peeking out! Very cool, interesting patterns on the metal too.</td>', 'I love the focus on this, the little eye peeking out! Very cool, interesting patterns on the metal too.', '2011-11-17 10:29:45.000000', NULL, 1),
(6597092, 983988, 94265, '<td valign="top">Beautiful. Great perspective, I like the muted colours, fantastic sharpness. Ribbon maybe?</td>', 'Beautiful. Great perspective, I like the muted colours, fantastic sharpness. Ribbon maybe?', '2011-11-17 11:16:12.000000', NULL, 1),
(6597102, 984062, 118154, '<td valign="top">Love the oldness you have here.</td>', 'Love the oldness you have here.', '2011-11-17 11:33:14.000000', NULL, 1),
