(6597773, 984130, 12611, '<td valign="top">I think the deep magenta is great.</td>', 'I think the deep magenta is great.', '2011-11-18 08:30:11.000000', NULL, 1),
(6597774, 984247, 12611, '<td valign="top">nice comp and framing.</td>', 'nice comp and framing.', '2011-11-18 08:30:31.000000', NULL, 1),
(6597775, 984141, 12611, '<td valign="top">great theme and treatment; well done.</td>', 'great theme and treatment; well done.', '2011-11-18 08:31:23.000000', NULL, 1),
(6597778, 984265, 12611, '<td valign="top">I appreciate the light, but the vignetting may be a bit dark. Great verticals and patterns.</td>', 'I appreciate the light, but the vignetting may be a bit dark. Great verticals and patterns.', '2011-11-18 08:33:21.000000', NULL, 1),
(6597781, 984099, 12611, '<td valign="top">I love in-town side door/ back doors, and this one has some great elements. The wood, the tan bricks, the leaf scatter, the lens flare. Even the black vignetted border is a good touch. Well done.</td>', 'I love in-town side door/ back doors, and this one has some great elements. The wood, the tan bricks, the leaf scatter, the lens flare. Even the black vignetted border is a good touch. Well done.', '2011-11-18 08:35:28.000000', NULL, 1),
(6597783, 983221, 12611, '<td valign="top">just enough in the shot to keep interest, and a great title.</td>', 'just enough in the shot to keep interest, and a great title.', '2011-11-18 08:36:14.000000', NULL, 1),
(6597787, 984262, 12611, '<td valign="top">One of the great things about this challenge is to take the ordinary and banal and transform it, into an abstract shape study, or a study on the ordinary and banal- and you have done that well. The tones and values of the yellows grab me, but the reflections below give some very good context. Top three for me.</td>', 'One of the great things about this challenge is to take the ordinary and banal and transform it, into an abstract shape study, or a study on the ordinary and banal- and you have done that well. The tones and values of the yellows grab me, but the reflections below give some very good context. Top three for me.', '2011-11-18 08:41:46.000000', NULL, 1),
(6597788, 984149, 12611, '<td valign="top">Great detail for a gray-scale shot, achieved with smoothness. well done.</td>', 'Great detail for a gray-scale shot, achieved with smoothness. well done.', '2011-11-18 08:42:37.000000', NULL, 1),
(6597789, 984042, 12611, '<td valign="top">Stone and leaves and metal- very nice- perhaps the crop constricts the composition, adds too much symmetry.</td>', 'Stone and leaves and metal- very nice- perhaps the crop constricts the composition, adds too much symmetry.', '2011-11-18 08:43:48.000000', NULL, 1),
