(6600777, 983221, 23098, '<td valign="top"><strike></strike></td>', '', '2011-11-22 09:06:51.000000', NULL, 1),
(6600813, 983930, 114225, '<td valign="top">This is very cool. Lucky you to be able to get this shot.</td>', 'This is very cool. Lucky you to be able to get this shot.', '2011-11-22 09:41:30.000000', NULL, 1),
(6600815, 984175, 114225, '<td valign="top">Great detail in this image.</td>', 'Great detail in this image.', '2011-11-22 09:41:57.000000', NULL, 1),
(6600817, 984246, 114225, '<td valign="top">Somehow, I feel this could have been much more powerful without the use of what looks like selective saturation.</td>', 'Somehow, I feel this could have been much more powerful without the use of what looks like selective saturation.', '2011-11-22 09:42:22.000000', NULL, 1),
(6600819, 984143, 114225, '<td valign="top">Old school. Nicely done.</td>', 'Old school. Nicely done.', '2011-11-22 09:42:42.000000', NULL, 1),
(6600821, 983931, 114225, '<td valign="top">Nice composition with showing a great sense of scale.</td>', 'Nice composition with showing a great sense of scale.', '2011-11-22 09:43:59.000000', NULL, 1),
(6600823, 983593, 114225, '<td valign="top">Nice job with the mood. Without those clouds, I don''t think this image would have worked as well.</td>', 'Nice job with the mood. Without those clouds, I don''t think this image would have worked as well.', '2011-11-22 09:44:36.000000', NULL, 1),
(6600830, 983608, 114225, '<td valign="top">Creative photograph. I could use it a little bit brighter.</td>', 'Creative photograph. I could use it a little bit brighter.', '2011-11-22 09:48:25.000000', NULL, 1),
(6600834, 984003, 114225, '<td valign="top">I think this could have been a more striking image with closer detail and more light.</td>', 'I think this could have been a more striking image with closer detail and more light.', '2011-11-22 09:51:32.000000', NULL, 1),
(6600837, 984163, 114225, '<td valign="top">Wonderfully composed and processed.</td>', 'Wonderfully composed and processed.', '2011-11-22 09:53:34.000000', NULL, 1),
(6600840, 983252, 114225, '<td valign="top">Definitely my favorite of the challenge. A very interesting composition.</td>', 'Definitely my favorite of the challenge. A very interesting composition.', '2011-11-22 09:58:09.000000', NULL, 1),
(6600880, 983428, 108331, '<td valign="top">Works well in black and white whith the long gras and gate.:) 8</td>', 'Works well in black and white whith the long gras and gate.:) 8', '2011-11-22 11:22:29.000000', NULL, 1),
(6600890, 983803, 108331, '<td valign="top">Nice coulors whith flowrs and little trees. I like the peacfull scene.</td>', 'Nice coulors whith flowrs and little trees. I like the peacfull scene.', '2011-11-22 11:26:21.000000', NULL, 1),
(6600902, 984061, 108331, '<td valign="top">Looks good whith the lamppost shadow falling on the door. Good picture.</td>', 'Looks good whith the lamppost shadow falling on the door. Good picture.', '2011-11-22 11:29:34.000000', NULL, 1),
(6600912, 983942, 108331, '<td valign="top">Very nice whith the boat and water in the background.</td>', 'Very nice whith the boat and water in the background.', '2011-11-22 11:52:46.000000', NULL, 1),
(6600914, 983322, 108331, '<td valign="top">This is nice with the orange rust and broken glass. Good luck :) 8</td>', 'This is nice with the orange rust and broken glass. Good luck :) 8', '2011-11-22 11:56:31.000000', NULL, 1),
(6600915, 984163, 108331, '<td valign="top">The sky and gold piant match. This is a Realy good picture, like it a lot.8</td>', 'The sky and gold piant match. This is a Realy good picture, like it a lot.8', '2011-11-22 11:59:04.000000', NULL, 1),
(6600917, 984247, 108331, '<td valign="top">I like the sharpnes of the gate. Good photo.8</td>', 'I like the sharpnes of the gate. Good photo.8', '2011-11-22 12:06:22.000000', NULL, 1),
(6600921, 984088, 108331, '<td valign="top">This photo is nice and sharp. I like the black door and brown walls 8</td>', 'This photo is nice and sharp. I like the black door and brown walls 8', '2011-11-22 12:12:18.000000', NULL, 1),
(6600922, 984130, 108331, '<td valign="top">The moss looks good with the gate and I like all the happy coulers.8</td>', 'The moss looks good with the gate and I like all the happy coulers.8', '2011-11-22 12:14:09.000000', NULL, 1),
(6600926, 984138, 108331, '<td valign="top">Creative with the 5 pound''s picture eye looking for any one who tries to open the case.7</td>', 'Creative with the 5 pound''s picture eye looking for any one who tries to open the case.7', '2011-11-22 12:18:19.000000', NULL, 1),
(6600929, 984168, 108331, '<td valign="top">The water drops make this picture well done!8</td>', 'The water drops make this picture well done!8', '2011-11-22 12:20:28.000000', NULL, 1),
(6601019, 984231, 140945, '<td valign="top">Not sure if I like the way this photos portrays the details in metals, although the detail in the wood is quite pleasing. I think the one colour element works well. I would have preferred this image if the shadow of the key was visible and wasn''t hidden behind the key.</td>', 'Not sure if I like the way this photos portrays the details in metals, although the detail in the wood is quite pleasing. I think the one colour element works well. I would have preferred this image if the shadow of the key was visible and wasn''t hidden behind the key.', '2011-11-22 15:36:42.000000', NULL, 1),
(6601022, 983338, 140945, '<td valign="top">I don''t really find this a pleasing image, it''s a little flat and it''s interesting feature isn''t very interesting. By turning the camera I think the photographer filled the frame well and saved the photo from the even less interesting details on the sides.</td>', 'I don''t really find this a pleasing image, it''s a little flat and it''s interesting feature isn''t very interesting. By turning the camera I think the photographer filled the frame well and saved the photo from the even less interesting details on the sides.', '2011-11-22 15:43:57.000000', NULL, 1),
(6601024, 984262, 140945, '<td valign="top">I find the composition pleasing, I like the limited range of colour (I mean.. it''s mostly variations of yellow). I love the simplicity of the photograph, it is "everyday details" in a minimalist way.</td>', 'I find the composition pleasing, I like the limited range of colour (I mean.. it''s mostly variations of yellow). I love the simplicity of the photograph, it is "everyday details" in a minimalist way.', '2011-11-22 15:53:33.000000', NULL, 1),
(6601025, 984273, 140945, '<td valign="top">Not much I like about this. The main thing that puts me off is all the greenness, whether this is the actual lighting or editing it isn''t good on the eye.</td>', 'Not much I like about this. The main thing that puts me off is all the greenness, whether this is the actual lighting or editing it isn''t good on the eye.', '2011-11-22 15:59:38.000000', NULL, 1),
(6601028, 984232, 140945, '<td valign="top">I like the idea and the emotion that is (nearly) pervade by the image of scared or shocked looking person reflected in the broken glass. It''s hard to not like the patterns in smashed glass. But.... I think the same picture could have been better. The photo lacks crispiness and I think the contrast and levels could have been edited better.</td>', 'I like the idea and the emotion that is (nearly) pervade by the image of scared or shocked looking person reflected in the broken glass. It''s hard to not like the patterns in smashed glass. But.... I think the same picture could have been better. The photo lacks crispiness and I think the contrast and levels could have been edited better.', '2011-11-22 16:06:05.000000', NULL, 1),
(6601029, 984267, 140945, '<td valign="top">Detail, detail, detail. Definitely can''t say the image doesn''t fulfil the brief. The editing has brought out the textures and details in the door, window and corrugated walls. 10 points for discovering the fantastic combination of textures. 10 points for the edit. But, for me, I don''t think the photo needed all the signs; if the composition was more focused on the door area I''d have scored it more.</td>', 'Detail, detail, detail. Definitely can''t say the image doesn''t fulfil the brief. The editing has brought out the textures and details in the door, window and corrugated walls. 10 points for discovering the fantastic combination of textures. 10 points for the edit. But, for me, I don''t think the photo needed all the signs; if the composition was more focused on the door area I''d have scored it more.', '2011-11-22 16:13:51.000000', NULL, 1),
(6601039, 983428, 140945, '<td valign="top">The main gate wants to draw my eyes to the far left of the photo (which I don''t find interesting), whilst I''m kind of drawn towards the tractor. But then should I be looking at the lock? No the Gate? Ok, I don''t know where to look. On the plus side, I like the lighting and contrast, I like black &amp; white.</td>', 'The main gate wants to draw my eyes to the far left of the photo (which I don''t find interesting), whilst I''m kind of drawn towards the tractor. But then should I be looking at the lock? No the Gate? Ok, I don''t know where to look. On the plus side, I like the lighting and contrast, I like black & white.', '2011-11-22 16:18:50.000000', NULL, 1),
(6601042, 984080, 140945, '<td valign="top">Is this a handle on a coffin? I believe they are mostly made of plastic nowadays. This looks metal. Anyway. I love wood, so I appreciate photos that capture the grain. Other than that it doesn''t inspire me to get up and take my camera out, or to view more work by the artist.</td>', 'Is this a handle on a coffin? I believe they are mostly made of plastic nowadays. This looks metal. Anyway. I love wood, so I appreciate photos that capture the grain. Other than that it doesn''t inspire me to get up and take my camera out, or to view more work by the artist.', '2011-11-22 16:24:09.000000', NULL, 1),
(6601049, 984258, 140945, '<td valign="top">Like. The window arches and shapes capture the eye, the prominence of the loading bay in the image is for some reason interesting me. Capturing the motion of a passing pedestrian gave the image something extra. Personally when capturing something that is mostly symmetric from straight on I prefer to get the line of symmetry in the centre of the image; the extra bit on the right hand side of this photo almost ruins the image.</td>', 'Like. The window arches and shapes capture the eye, the prominence of the loading bay in the image is for some reason interesting me. Capturing the motion of a passing pedestrian gave the image something extra. Personally when capturing something that is mostly symmetric from straight on I prefer to get the line of symmetry in the centre of the image; the extra bit on the right hand side of this photo almost ruins the image.', '2011-11-22 16:33:31.000000', NULL, 1),
(6601050, 983977, 140945, '<td valign="top">Some nice details, but I don''t like the photo, sorry.</td>', 'Some nice details, but I don''t like the photo, sorry.', '2011-11-22 16:35:57.000000', NULL, 1),
(6601051, 984105, 140945, '<td valign="top">Another image with some lovely details. Unfortunately I find the photo flat and lifeless. I touch of editing could have brought the image to life, more contrast maybe, definitely needs some saturation.</td>', 'Another image with some lovely details. Unfortunately I find the photo flat and lifeless. I touch of editing could have brought the image to life, more contrast maybe, definitely needs some saturation.', '2011-11-22 16:38:44.000000', NULL, 1),
(6601056, 984165, 140945, '<td valign="top">Whilst the subject isn''t very interesting, the photo makes it interesting (seems to be what the challenge is asking for). Obviously a photo taken by somebody that knows how light works and how to use their camera. The depth of field is very pleasing. The texture of the locks metal is beautifully captured and then contrasted by the smooth and shiney keys. The yellowy gold of the lock works really well with the orangey red of the floor. Great contrast and levels too.</td>', 'Whilst the subject isn''t very interesting, the photo makes it interesting (seems to be what the challenge is asking for). Obviously a photo taken by somebody that knows how light works and how to use their camera. The depth of field is very pleasing. The texture of the locks metal is beautifully captured and then contrasted by the smooth and shiney keys. The yellowy gold of the lock works really well with the orangey red of the floor. Great contrast and levels too.', '2011-11-22 16:45:45.000000', NULL, 1),
(6601066, 984157, 140945, '<td valign="top">The patterns and symmetry are pleasing.</td>', 'The patterns and symmetry are pleasing.', '2011-11-22 17:02:42.000000', NULL, 1),
(6601076, 983803, 140945, '<td valign="top">I like this photo, it grabbed me straight away. I like the way all the colour is through the windows. Whilst the lighting on the wood highlights it''s grain and helps frame the image.</td>', 'I like this photo, it grabbed me straight away. I like the way all the colour is through the windows. Whilst the lighting on the wood highlights it''s grain and helps frame the image.', '2011-11-22 17:21:57.000000', NULL, 1),
(6601077, 984035, 140945, '<td valign="top">Beautiful dog, but I''m not sure if the photo displays the details of the subject (the door) particularly well. The photo itself doesn''t do it for me.</td>', 'Beautiful dog, but I''m not sure if the photo displays the details of the subject (the door) particularly well. The photo itself doesn''t do it for me.', '2011-11-22 17:24:28.000000', NULL, 1),
(6601079, 984256, 140945, '<td valign="top">If I put my hand over the bottom half of this photo I''d probably have scored it higher. The top half has a moody feel, a noisy grain lots of different forms of details. But if you include the bottom half I think the image is over-crowded and a little confused.</td>', 'If I put my hand over the bottom half of this photo I''d probably have scored it higher. The top half has a moody feel, a noisy grain lots of different forms of details. But if you include the bottom half I think the image is over-crowded and a little confused.', '2011-11-22 17:28:25.000000', NULL, 1),
(6601080, 984211, 140945, '<td valign="top">Bit too abstract. Not that interesting.</td>', 'Bit too abstract. Not that interesting.', '2011-11-22 17:29:36.000000', NULL, 1),
(6601085, 983312, 140945, '<td valign="top">I really quite like this photo. It''s not overly complicated, captures all the details of the paint and lack paint, has pleasant lighting and nicely place shadows. Bravo.</td>', 'I really quite like this photo. It''s not overly complicated, captures all the details of the paint and lack paint, has pleasant lighting and nicely place shadows. Bravo.', '2011-11-22 17:39:28.000000', NULL, 1),
(6601087, 984279, 140945, '<td valign="top">Nice wood, Nice handles. No hole for the lock is a feature that appeals to me. I find the rest hideous. Having said that, the levels and contrast and saturation and such like are good.</td>', 'Nice wood, Nice handles. No hole for the lock is a feature that appeals to me. I find the rest hideous. Having said that, the levels and contrast and saturation and such like are good.', '2011-11-22 17:43:06.000000', NULL, 1),
(6601092, 984061, 140945, '<td valign="top">With the lamp right in front of the door its important to choose the right angle to take this photograph, I''m not convinced the artist did, but I''m not convinced he/she didn''t. What I''m trying to say is that the placement of the lamp is a little awkward, whilst the angle of the door is good and it doesn''t look like there would actually be a better place to take the photo from. I feel the same about the shadow of the lamp. The lighting in the photo is great, only that time of day would produce that lighting, but for me the shadow of the lamp is in the wrong place.<br/>In the end: colours, details, crispness and editing all good. Composition: unsure.</td>', 'With the lamp right in front of the door its important to choose the right angle to take this photograph, I''m not convinced the artist did, but I''m not convinced he/she didn''t. What I''m trying to say is that the placement of the lamp is a little awkward, whilst the angle of the door is good and it doesn''t look like there would actually be a better place to take the photo from. I feel the same about the shadow of the lamp. The lighting in the photo is great, only that time of day would produce that lighting, but for me the shadow of the lamp is in the wrong place.In the end: colours, details, crispness and editing all good. Composition: unsure.', '2011-11-22 17:48:59.000000', NULL, 1),
(6601099, 984125, 140945, '<td valign="top">Love this gate. I think the photo could be dark in places, more contrast. I also think the photo would benefit from cropping everything below the step. Still I like it.</td>', 'Love this gate. I think the photo could be dark in places, more contrast. I also think the photo would benefit from cropping everything below the step. Still I like it.', '2011-11-22 18:00:31.000000', NULL, 1),
(6601102, 984183, 140945, '<td valign="top">Its not interesting, is it?</td>', 'Its not interesting, is it?', '2011-11-22 18:03:30.000000', NULL, 1),
(6601104, 984151, 140945, '<td valign="top">I like it''s contrast and metalness. Although its not the most interesting of photos.</td>', 'I like it''s contrast and metalness. Although its not the most interesting of photos.', '2011-11-22 18:05:08.000000', NULL, 1),
(6601112, 984193, 140945, '<td valign="top">This is wonderful, I''d be tempted to give it a 10 if the top left corner was in focus. Detail, lighting, edit and composition very good.</td>', 'This is wonderful, I''d be tempted to give it a 10 if the top left corner was in focus. Detail, lighting, edit and composition very good.', '2011-11-22 18:19:13.000000', NULL, 1),
(6601114, 984019, 18367, '<td valign="top">Nice shot of "La porte St.Jean in Quebec City.  Good luck in the challenge.</td>', 'Nice shot of "La porte St.Jean in Quebec City.  Good luck in the challenge.', '2011-11-22 18:23:25.000000', NULL, 1),
(6601124, 984088, 140945, '<td valign="top">I like the composition of this image. Lovely symmetry. Plenty of tonal variation and interesting details. I don''t like the white sky (I get them in my photos all the time and it really annoys me)</td>', 'I like the composition of this image. Lovely symmetry. Plenty of tonal variation and interesting details. I don''t like the white sky (I get them in my photos all the time and it really annoys me)', '2011-11-22 18:41:58.000000', NULL, 1),
(6601139, 984168, 124815, '<td valign="top">The weepy lock. Simple and powerful.</td>', 'The weepy lock. Simple and powerful.', '2011-11-22 19:07:45.000000', NULL, 1),
(6601140, 983988, 124815, '<td valign="top">Il Battistero di San Giovanni of Florence. Surely the gates of paradise. <br/>Great, absolute great peeking inside the paradise where the birds are chirping and where there is no sadness or pain....</td>', 'Il Battistero di San Giovanni of Florence. Surely the gates of paradise. Great, absolute great peeking inside the paradise where the birds are chirping and where there is no sadness or pain....', '2011-11-22 19:07:48.000000', NULL, 1),
(6601141, 984176, 124815, '<td valign="top">Like a vision.<br/>bump to 8</td>', 'Like a vision.bump to 8', '2011-11-22 19:07:53.000000', NULL, 1),
(6601142, 984019, 124815, '<td valign="top">Noel approaching! Such a good feeling here!</td>', 'Noel approaching! Such a good feeling here!', '2011-11-22 19:07:58.000000', NULL, 1),
(6601143, 984211, 124815, '<td valign="top">So glad there are some clean doors! <br/>Bump up</td>', 'So glad there are some clean doors! Bump up', '2011-11-22 19:08:05.000000', NULL, 1),
(6601144, 984077, 124815, '<td valign="top">A bit of fresh air here. Good.</td>', 'A bit of fresh air here. Good.', '2011-11-22 19:08:10.000000', NULL, 1),
(6601145, 984124, 124815, '<td valign="top">I see them also!</td>', 'I see them also!', '2011-11-22 19:08:13.000000', NULL, 1),
(6601147, 983459, 124815, '<td valign="top">Nice and breezy</td>', 'Nice and breezy', '2011-11-22 19:09:33.000000', NULL, 1),
(6601148, 983493, 124815, '<td valign="top">The saturation is pushed way to much</td>', 'The saturation is pushed way to much', '2011-11-22 19:10:03.000000', NULL, 1),
(6601149, 983530, 124815, '<td valign="top">Nice image though. Too much processing. Something happened in this challenge since I found more than 70% of the images pushed too much and thus losing quality.</td>', 'Nice image though. Too much processing. Something happened in this challenge since I found more than 70% of the images pushed too much and thus losing quality.', '2011-11-22 19:10:23.000000', NULL, 1),
(6601151, 983679, 124815, '<td valign="top">A great find but so over processed!</td>', 'A great find but so over processed!', '2011-11-22 19:11:17.000000', NULL, 1),
(6601156, 984122, 140945, '<td valign="top">Firstly, I think the title is terrible. Secondly, the depth of field is too shallow, I like shallow, but for this subject I wanted to see more of the nuts and bolts. Thirdly, I like the subject, the little carved crosses (x''s) are cute, the half hidden lock gives the viewer something missing that add intrigue!!</td>', 'Firstly, I think the title is terrible. Secondly, the depth of field is too shallow, I like shallow, but for this subject I wanted to see more of the nuts and bolts. Thirdly, I like the subject, the little carved crosses (x''s) are cute, the half hidden lock gives the viewer something missing that add intrigue!!', '2011-11-22 19:16:35.000000', NULL, 1),
(6601159, 984077, 35804, '<td valign="top">Love the shock of color...very cool.</td>', 'Love the shock of color...very cool.', '2011-11-22 19:20:06.000000', NULL, 1),
(6601161, 984175, 140945, '<td valign="top">Not the sort of ordinary details that most people see everyday, but I like it. With the exception of the motif, the details are ordinary. Some panels look a little beat up which gives the picture an honesty. I like.</td>', 'Not the sort of ordinary details that most people see everyday, but I like it. With the exception of the motif, the details are ordinary. Some panels look a little beat up which gives the picture an honesty. I like.', '2011-11-22 19:20:35.000000', NULL, 1),
(6601163, 984019, 140945, '<td valign="top">Don''t think this is a good photo (messy no real focal point) and I don''t think it fits the challenge brief.</td>', 'Don''t think this is a good photo (messy no real focal point) and I don''t think it fits the challenge brief.', '2011-11-22 19:22:53.000000', NULL, 1),
(6601164, 983459, 35804, '<td valign="top">Really enjoyable...as my eye travels the image I find myself wishing I were there.</td>', 'Really enjoyable...as my eye travels the image I find myself wishing I were there.', '2011-11-22 19:22:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6601167, 983508, 140945, '<td valign="top">This photo is such bad quality I can''t see the details that the author was trying to photograph.</td>', 'This photo is such bad quality I can''t see the details that the author was trying to photograph.', '2011-11-22 19:26:16.000000', NULL, 1),
(6601169, 984269, 140945, '<td valign="top">This is pretty, many shapes, many layers of detail, I like the fact that you can see that the door handle has been moved or replaced. Different light conditions could have improved this photo.</td>', 'This is pretty, many shapes, many layers of detail, I like the fact that you can see that the door handle has been moved or replaced. Different light conditions could have improved this photo.', '2011-11-22 19:28:52.000000', NULL, 1),
(6601170, 983931, 140945, '<td valign="top">The lighting in this photo gives it an almost magical mystical feel. I like the sparsity of colour and the roughness of the wall.</td>', 'The lighting in this photo gives it an almost magical mystical feel. I like the sparsity of colour and the roughness of the wall.', '2011-11-22 19:30:57.000000', NULL, 1),
(6601171, 984145, 140945, '<td valign="top">WHITE WHITE WHITE. Too much white, seems to have lost some of the detail to the whiteness. On the other hand, it''s clean with simple but interesting shadows.</td>', 'WHITE WHITE WHITE. Too much white, seems to have lost some of the detail to the whiteness. On the other hand, it''s clean with simple but interesting shadows.', '2011-11-22 19:32:39.000000', NULL, 1),
(6601172, 984188, 140945, '<td valign="top">I like this. Everything seems well placed in the image. Good contrast, good highlights and lowlights.</td>', 'I like this. Everything seems well placed in the image. Good contrast, good highlights and lowlights.', '2011-11-22 19:35:04.000000', NULL, 1),
(6601177, 983981, 140945, '<td valign="top">I''d like to see high contrast in this photo, without comprising the brightness too much,</td>', 'I''d like to see high contrast in this photo, without comprising the brightness too much,', '2011-11-22 19:40:27.000000', NULL, 1),
(6601181, 984212, 140945, '<td valign="top">Yes, some people have taken the challenge title "Doors, Gates, Knobs, Locks &amp; Handles", gone away and taken a photo of one of those things, others understood brief of capturing the beautiful details in those everyday things. Some people, like the artist behind this photo, did the right thing. This is art, it tells a story, good vs evil. It''s beautiful and it fulfils the challenge title and brief. What more can I say than, fantastic lighting, composition,  detail, brilliant choice for depth of field. Very pleasing to the eye.</td>', 'Yes, some people have taken the challenge title "Doors, Gates, Knobs, Locks & Handles", gone away and taken a photo of one of those things, others understood brief of capturing the beautiful details in those everyday things. Some people, like the artist behind this photo, did the right thing. This is art, it tells a story, good vs evil. It''s beautiful and it fulfils the challenge title and brief. What more can I say than, fantastic lighting, composition,  detail, brilliant choice for depth of field. Very pleasing to the eye.', '2011-11-22 19:46:43.000000', NULL, 1),
(6601182, 984136, 140945, '<td valign="top">Simple but effective. I can see that he photographer has purposefully turned the key to that angle that proves both a good key shape and a good key shadow shape.</td>', 'Simple but effective. I can see that he photographer has purposefully turned the key to that angle that proves both a good key shape and a good key shadow shape.', '2011-11-22 19:50:11.000000', NULL, 1),
(6601184, 983640, 140945, '<td valign="top">Good photo, good edit, not sure how well it shows off  the details of the everyday ordinary things.</td>', 'Good photo, good edit, not sure how well it shows off  the details of the everyday ordinary things.', '2011-11-22 19:51:42.000000', NULL, 1),
